import { Component, OnInit, OnDestroy } from '@angular/core';
import { Router, NavigationEnd } from '@angular/router';
import { House } from '../../../house/models/house.model';
import { HouseItemComponent } from '../../../house/components/house-item/house-item.component';
import { Subscription } from 'rxjs';
import { filter } from 'rxjs/operators';
import { NgIf } from '@angular/common';
import { AnkaWindowComponent } from '../anka-window/anka-window.component';
import { AnkaBubbleComponent } from '../anka-bubble/anka-bubble.component';
import { SeoService } from '../../../core/services/seo.service';

@Component({
  selector: 'app-anka-list',
  standalone: true,
  imports: [HouseItemComponent, NgIf, AnkaWindowComponent, AnkaBubbleComponent],
  templateUrl: './anka-list.component.html',
  styleUrl: './anka-list.component.scss'
})
export class AnkaListComponent implements OnInit, OnDestroy {
  houselist: House[] = [];
  message: string = '';
  private routerSub!: Subscription;

  constructor(private router: Router, private seoService: SeoService) {
    // Initialize data from current state (first load)
    this.updateData();
  }

  ngOnInit(): void {
    // Subscribe to navigation events to handle reloads (when query params change)
    this.routerSub = this.router.events.pipe(
      filter(event => event instanceof NavigationEnd)
    ).subscribe(() => {
      this.updateData();
    });
  }

  ngOnDestroy(): void {
    if (this.routerSub) {
      this.routerSub.unsubscribe();
    }
  }

  private updateData() {
    const state = history.state;
    // Check if we have data in state
    if (state && state.data) {
      console.log("Anka List Updated:", state.data);
      this.message = state.data.message;
      this.houselist = state.data.results || [];

      // Update SEO Tags
      let seoTitle = "Résultats de recherche";
      if (state.data.criteria) {
        const c = state.data.criteria;
        if (c.Type && c.city) seoTitle = `${c.Type} à ${c.city}`;
        else if (c.city) seoTitle = `Biens immobiliers à ${c.city}`;
        else if (c.Type) seoTitle = `${c.Type} disponibles`;
      }

      this.seoService.updateMetaTags({
        title: seoTitle,
        description: this.message,
        url: window.location.href
      });
    }
  }
}
